Input: {"question": "When was the Giff first held?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0374-f5f32368bb91:d00", "start": 0, "end": 178, "text": "Geneva International Film Festival The Geneva International Film Festival // GIFF has been exploring the relationship between cinema, television, and digital creation since 1995."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0374-f5f32368bb91:d00", "start": 179, "end": 392, "text": "Since its inception in 1995, the GIFF has been exploring the links between cinema, television and digital art, while defending the place of the author in the artistic process, regardless of the audiovisual format."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0374-f5f32368bb91:d00", "start": 393, "end": 534, "text": "More than a cinema festival, the GIFF is at the crossroads of genres and disciplines, a place for experimenting, meeting others and partying."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0374-f5f32368bb91:d00", "start": 535, "end": 636, "text": "Every year over nine days, it offers a series of experiences focused on image, sound and new forms of"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0374-f5f32368bb91:d01", "start": 0, "end": 261, "text": "Guwahati International Film Festival The Guwahati International Film Festival (GIFF) () is an annual film festival held in Guwahati, Assam, India.The State Government-owned Jyoti Chitraban (Film Studio) Society organised the festival in association with the Dr."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0374-f5f32368bb91:d01", "start": 262, "end": 328, "text": "Bhupen Hazarika Regional Government Film and Television Institute."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0374-f5f32368bb91:d01", "start": 329, "end": 508, "text": "The first ever Guwahati International Film Festival (GIFF) to be held in northeast India, which will be inaugurated on October 28, 2017 by Assam Chief Minister Sarbananda Sonowal."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0374-f5f32368bb91:d01", "start": 509, "end": 688, "text": "The Assam government supported festival began on October 28 with screening of the Oscar winning ‘The Salesman’, directed by Asghar Farhadi and produced by a joint collaboration of"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0374-f5f32368bb91:d02", "start": 0, "end": 45, "text": "that it is the biggest industry of the state."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0374-f5f32368bb91:d02", "start": 46, "end": 137, "text": "The headquarters of the Assam Branch Indian Tea Association (ABITA) is located at Guwahati."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0374-f5f32368bb91:d02", "start": 138, "end": 330, "text": "The Guwahati Tea Auction Centre (GTAC), located adjacent to the capital complex at Dispur, is the world's largest CTC tea auction centre and the second largest in terms of total tea auctioned."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0374-f5f32368bb91:d02", "start": 331, "end": 440, "text": "The inaugural sale took place on 25 September 1970 and the first lot of tea was auctioned at the price of Rs."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0374-f5f32368bb91:d02", "start": 441, "end": 495, "text": "42.50 which, during those days, was a big achievement."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0374-f5f32368bb91:d02", "start": 496, "end": 584, "text": "Many centralised, private and international banks have set up their branches in the city"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0374-f5f32368bb91:d03", "start": 0, "end": 50, "text": "Tea Association ( ABITA ) is located at Guwahati ."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0374-f5f32368bb91:d03", "start": 51, "end": 249, "text": "The Guwahati Tea Auction Centre ( GTAC ) , located adjacent to the capital complex at Dispur , is the world 's largest CTC tea auction center and the second largest in terms of total tea auctioned ."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0374-f5f32368bb91:d03", "start": 250, "end": 423, "text": "The inaugural sale took place on 25 September 1970 and the first lot of tea was auctioned at the price of ₹ 42.50 which , during those days , was a significant achievement ."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0374-f5f32368bb91:d03", "start": 424, "end": 520, "text": "In the month of August 2019 , a kilogram of Maijan Orthodox Golden tea sold for a record-setting"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0374-f5f32368bb91:d04", "start": 0, "end": 71, "text": "“ city of temples ” due to the existence of many ancient temples here ."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0374-f5f32368bb91:d04", "start": 72, "end": 217, "text": "Let us discover the multifaceted aspects of the Guwahati city- Guwahati Past and Present The history of Gauhati goes back to thousands of years ."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0374-f5f32368bb91:d04", "start": 218, "end": 358, "text": "The mention of the city has been made in ancient puranas and epic where Guwahati has been referred to as one of the ancient cities of Asia ."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0374-f5f32368bb91:d04", "start": 359, "end": 495, "text": "The Kamakhya , Basistha and Navagraha temples which have an existence here since ages prove the existence of Guwahati in ancient times ."}, "D5S5": {"document_number": 5, "doc_id": "ramdocs-0374-f5f32368bb91:d04", "start": 496, "end": 550, "text": "The Ambari excavations trace the existence of the city"}}, "original_cards": [{"doc_id": "ramdocs-0374-f5f32368bb91:d00", "card_id": "ramdocs-0374-f5f32368bb91:d00:c0", "entity": "Giff", "scope": "When was the Giff first held?", "claim": "The Giff was first held in 1995.", "answer": "1995", "quote": "Geneva International Film Festival The Geneva International Film Festival // GIFF has been exploring the relationship between cinema, television, and digital creation since 1995. Since its inception in 1995, the GIFF has been exploring the links between cinema, television and digital art, while defending the place of the author in the artistic process, regardless of the audiovisual format.", "original_document_number": 1}, {"doc_id": "ramdocs-0374-f5f32368bb91:d01", "card_id": "ramdocs-0374-f5f32368bb91:d01:c0", "entity": "Giff", "scope": "first held", "claim": "The first ever Guwahati International Film Festival (GIFF) was held on October 28, 2017.", "answer": "October 28, 2017", "quote": "The first ever Guwahati International Film Festival (GIFF) to be held in northeast India, which will be inaugurated on October 28, 2017 by Assam Chief Minister Sarbananda Sonowal.", "original_document_number": 2}, {"doc_id": "ramdocs-0374-f5f32368bb91:d02", "card_id": "ramdocs-0374-f5f32368bb91:d02:c0", "entity": "Giff", "scope": "The inaugural sale at the Guwahati Tea Auction Centre (GTAC)", "claim": "The inaugural sale (Giff) took place on 25 September 1970.", "answer": "25 September 1970", "quote": "The inaugural sale took place on 25 September 1970 and the first lot of tea was auctioned at the price of Rs.", "original_document_number": 3}, {"doc_id": "ramdocs-0374-f5f32368bb91:d03", "card_id": "ramdocs-0374-f5f32368bb91:d03:c0", "entity": "Giff", "scope": "first held", "claim": "The Giff was first held on 25 September 1970.", "answer": "25 September 1970", "quote": "The inaugural sale took place on 25 September 1970 and the first lot of tea was auctioned at the price of ₹ 42.50 which , during those days , was a significant achievement .", "original_document_number": 4}], "current_answers": ["1995", "October 28, 2017", "25 September 1970"], "candidate_answers": [{"candidate_id": "R0", "answer": "1995", "origin": "initial"}, {"candidate_id": "R1", "answer": "October 28, 2017", "origin": "initial"}, {"candidate_id": "R2", "answer": "25 September 1970", "origin": "coverage_addition"}], "requested_slot_hint":